import math

training = [
    ("winner claim your free prize", 1), ("free cash now", 1), ("cash prize winner", 1),
    ("urgent claim cash", 1), ("meeting moved to friday", 0), ("homework due friday", 0),
    ("lunch meeting tomorrow", 0), ("see the homework notes", 0),
]


def rule(text):
    return "free money" in text or "free prize" in text


counts = {1: {}, 0: {}}
for text, label in training:
    for word in text.split():
        counts[label][word] = counts[label].get(word, 0) + 1
vocab = set(counts[0]) | set(counts[1])
total = {c: sum(counts[c].values()) + len(vocab) for c in (0, 1)}
weight = {w: math.log((counts[1].get(w, 0) + 1) / total[1]) - math.log((counts[0].get(w, 0) + 1) / total[0]) for w in vocab}

print("learned word weights (positive = spammy):")
ranked = sorted(weight, key=lambda w: (-weight[w], w))      # ties broken alphabetically
for w in ranked[:4] + ranked[-3:]:
    print(f"  {w:9} {weight[w]:+.2f}")


def learned(text):
    return sum(weight.get(w, 0) for w in text.split()) > 0


print()
for email in ["claim your cash prize now", "homework due at the meeting", "free prize inside"]:
    print(f"{email:30} rule: {'spam' if rule(email) else 'ok':4}   learned: {'spam' if learned(email) else 'ok'}")

import random

# plant height in cm -> got enough sun (1) or not (0), with a little noise
data = [(h, 1 if h >= 30 else 0) for h in range(10, 50, 2)]
data[3] = (data[3][0], 1)                      # one noisy label
random.Random(42).shuffle(data)
split = int(len(data) * 0.75)
train, test = data[:split], data[split:]
print(f"{len(train)} training examples, {len(test)} test examples")

memory = {h: label for h, label in train}


def memorizer(h):
    return memory.get(h, 0)                    # unseen input: guess 0


best = max(range(10, 50), key=lambda t: sum((h >= t) == bool(y) for h, y in train))


def threshold_model(h):
    return 1 if h >= best else 0


def accuracy(model, examples):
    return sum(model(h) == y for h, y in examples) / len(examples)


for name, model in [("memorizer", memorizer), (f"threshold >= {best}", threshold_model)]:
    print(f"{name:16} train {accuracy(model, train):.0%}   test {accuracy(model, test):.0%}")

incomes = [20, 30, 40, 50, 60, 70, 80, 90]
history = [("A", inc, 1 if inc >= 40 else 0) for inc in incomes] + \
          [("B", inc, 1 if inc >= 70 else 0) for inc in incomes]     # past decisions were harsher for B


def fit_threshold(rows):
    return max(range(0, 101, 10), key=lambda t: sum((inc >= t) == bool(ok) for _, inc, ok in rows))


thresholds = {g: fit_threshold([r for r in history if r[0] == g]) for g in "AB"}
print("learned income thresholds:", thresholds)


def model(group, income):
    return income >= thresholds[group]


for group in "AB":
